import { createFileRoute } from '@tanstack/react-router'
import { View } from '@/components/pages/projects/$projectId/firewall/View'
import {
  parseFirewallListSearch,
  type FirewallResourceType,
} from '@/lib/firewall/conditions'
import { pageTitle } from '@/lib/utils/page-title'

export type FirewallListSearch = {
  resourceType?: FirewallResourceType
  resourceId?: string
}

export const Route = createFileRoute('/_public/projects/$projectId/firewall/')({
  head: () => ({ meta: [{ title: pageTitle('Firewall') }] }),
  validateSearch: (search: Record<string, unknown>): FirewallListSearch =>
    parseFirewallListSearch(search) ?? {},
  component: View,
})
/**
 * Function Selector
 *
 * Form dropdown over the shared ResourceSearchPopover (same list as the
 * function detail title switcher).
 */

import { useEffect, useMemo, useState } from 'react'
import { ChevronDown, Terminal } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { RuntimeIcon } from '@/components/global/shared/RuntimeIcon'
import {
  ResourceSearchPopover,
  type ResourceSearchListItem,
} from '@/components/global/shared/ResourceSearchPopover'
import { projectFunctionQueryOptions } from '@/lib/react-query/hooks'
import { useQuery } from '@tanstack/react-query'
import { useT } from '@/lib/i18n/translate'
import { cn } from '@/lib/utils'

export interface FunctionSelectorProps {
  projectId: string | null | undefined
  value: string
  onValueChange: (functionId: string) => void
  placeholder?: string
  disabled?: boolean
  triggerClassName?: string
  contentClassName?: string
}

export function FunctionSelector({
  projectId,
  value,
  onValueChange,
  placeholder = 'Select function',
  disabled = false,
  triggerClassName,
  contentClassName,
}: FunctionSelectorProps) {
  const t = useT()
  const [selectedSnapshot, setSelectedSnapshot] =
    useState<ResourceSearchListItem | null>(null)

  useEffect(() => {
    if (!value) {
      setSelectedSnapshot(null)
      return
    }
    if (selectedSnapshot && selectedSnapshot.id !== value) {
      setSelectedSnapshot(null)
    }
  }, [value, selectedSnapshot])

  const { data: selectedFunction } = useQuery({
    ...projectFunctionQueryOptions(projectId, value || undefined),
    enabled: !!projectId && !!value,
  })

  const pinnedItems = useMemo((): ResourceSearchListItem[] => {
    if (selectedFunction) {
      return [
        {
          id: selectedFunction.$id,
          label: selectedFunction.name || 'Unnamed function',
          runtime: selectedFunction.runtime,
        },
      ]
    }
    if (selectedSnapshot?.id === value) return [selectedSnapshot]
    return []
  }, [selectedFunction, selectedSnapshot, value])

  const selectedLabel =
    selectedFunction?.name ||
    (selectedSnapshot?.id === value ? selectedSnapshot.label : undefined) ||
    ''
  const selectedRuntime =
    selectedFunction?.runtime ??
    (selectedSnapshot?.id === value ? selectedSnapshot.runtime : undefined) ??
    ''

  return (
    <ResourceSearchPopover
      kind="function"
      projectId={projectId}
      selectedId={value}
      onSelect={(id, item) => {
        setSelectedSnapshot(item)
        onValueChange(id)
      }}
      pinnedItems={pinnedItems}
      disabled={disabled || !projectId}
      className="w-full min-w-0"
      contentClassName={cn(
        'w-[var(--radix-popover-trigger-width)] min-w-[240px]',
        contentClassName,
      )}
      trigger={
        <Button
          type="button"
          variant="outline"
          role="combobox"
          disabled={disabled || !projectId}
          className={cn(
            'h-9 w-full justify-between gap-2 text-[13px] font-normal',
            !value && 'text-muted-foreground',
            triggerClassName,
          )}
        >
          <span className="flex min-w-0 items-center gap-2 truncate">
            {value && selectedLabel ? (
              <RuntimeIcon
                runtime={selectedRuntime}
                size="sm"
                className="h-4 w-4 shrink-0 text-muted-foreground"
              />
            ) : (
              <Terminal className="h-4 w-4 shrink-0 text-muted-foreground" />
            )}
            <span className="truncate">
              {value && selectedLabel ? selectedLabel : t(placeholder)}
            </span>
          </span>
          <ChevronDown className="h-4 w-4 shrink-0 opacity-50" />
        </Button>
      }
    />
  )
}
/**
 * Site Selector
 *
 * Form dropdown over the shared ResourceSearchPopover (same list as the
 * site detail title switcher).
 */

import { useEffect, useMemo, useState } from 'react'
import { ChevronDown, Globe } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { FrameworkIcon } from '@/components/global/shared/FrameworkIcon'
import {
  ResourceSearchPopover,
  type ResourceSearchListItem,
} from '@/components/global/shared/ResourceSearchPopover'
import { siteQueryOptions } from '@/lib/react-query/hooks'
import { useQuery } from '@tanstack/react-query'
import { useT } from '@/lib/i18n/translate'
import { cn } from '@/lib/utils'

function getSiteFramework(site: {
  buildFramework?: string
  buildFrameworkId?: string
  framework?: string
}): string | undefined {
  return site.buildFramework || site.buildFrameworkId || site.framework
}

export interface SiteSelectorProps {
  projectId: string | null | undefined
  value: string
  onValueChange: (siteId: string) => void
  placeholder?: string
  disabled?: boolean
  triggerClassName?: string
  contentClassName?: string
}

export function SiteSelector({
  projectId,
  value,
  onValueChange,
  placeholder = 'Select site',
  disabled = false,
  triggerClassName,
  contentClassName,
}: SiteSelectorProps) {
  const t = useT()
  const [selectedSnapshot, setSelectedSnapshot] =
    useState<ResourceSearchListItem | null>(null)

  useEffect(() => {
    if (!value) {
      setSelectedSnapshot(null)
      return
    }
    if (selectedSnapshot && selectedSnapshot.id !== value) {
      setSelectedSnapshot(null)
    }
  }, [value, selectedSnapshot])

  const { data: selectedSite } = useQuery({
    ...siteQueryOptions(projectId, value || undefined),
    enabled: !!projectId && !!value,
  })

  const selectedFramework = selectedSite
    ? getSiteFramework(
        selectedSite as {
          buildFramework?: string
          buildFrameworkId?: string
          framework?: string
        },
      )
    : selectedSnapshot?.id === value
      ? selectedSnapshot.framework
      : undefined

  const pinnedItems = useMemo((): ResourceSearchListItem[] => {
    if (selectedSite) {
      return [
        {
          id: selectedSite.$id,
          label: selectedSite.name || 'Unnamed site',
          framework: getSiteFramework(
            selectedSite as {
              buildFramework?: string
              buildFrameworkId?: string
              framework?: string
            },
          ),
        },
      ]
    }
    if (selectedSnapshot?.id === value) return [selectedSnapshot]
    return []
  }, [selectedSite, selectedSnapshot, value])

  const selectedLabel =
    selectedSite?.name ||
    (selectedSnapshot?.id === value ? selectedSnapshot.label : undefined) ||
    ''

  return (
    <ResourceSearchPopover
      kind="site"
      projectId={projectId}
      selectedId={value}
      onSelect={(id, item) => {
        setSelectedSnapshot(item)
        onValueChange(id)
      }}
      pinnedItems={pinnedItems}
      disabled={disabled || !projectId}
      className="w-full min-w-0"
      contentClassName={cn(
        'w-[var(--radix-popover-trigger-width)] min-w-[240px]',
        contentClassName,
      )}
      trigger={
        <Button
          type="button"
          variant="outline"
          role="combobox"
          disabled={disabled || !projectId}
          className={cn(
            'h-9 w-full justify-between gap-2 text-[13px] font-normal',
            !value && 'text-muted-foreground',
            triggerClassName,
          )}
        >
          <span className="flex min-w-0 items-center gap-2 truncate">
            {value && selectedLabel ? (
              <FrameworkIcon
                framework={selectedFramework}
                size="sm"
                className="h-4 w-4 shrink-0"
              />
            ) : (
              <Globe className="h-4 w-4 shrink-0 text-muted-foreground" />
            )}
            <span className="truncate">
              {value && selectedLabel ? selectedLabel : t(placeholder)}
            </span>
          </span>
          <ChevronDown className="h-4 w-4 shrink-0 opacity-50" />
        </Button>
      }
    />
  )
}
import { useState, type LucideIcon } from 'react'
import {
  Activity,
  AppWindow,
  Building,
  Building2,
  Cable,
  Check,
  ChevronDown,
  Clock,
  Cloud,
  Compass,
  Cookie,
  Fingerprint,
  Globe,
  Globe2,
  Hash,
  KeyRound,
  Languages,
  LocateFixed,
  Mailbox,
  MapPin,
  Monitor,
  Network,
  Route,
  SearchCode,
  Send,
  Server,
  ShieldCheck,
  Tags,
  Timer,
  UserRound,
  Wifi,
} from 'lucide-react'
import { Button } from '@/components/ui/button'
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from '@/components/ui/command'
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/components/ui/popover'
import { useModalAwarePopover } from '@/lib/layout/modal-portal-host'
import {
  FIREWALL_CONDITION_ATTRIBUTE_GROUPS,
  FIREWALL_CONDITION_ATTRIBUTES,
  isAttributeAvailable,
  isPremiumAttribute,
  type FirewallConditionAttribute,
  type FirewallResourceType,
} from '@/lib/firewall/conditions'
import { useT } from '@/lib/i18n/translate'
import { cn } from '@/lib/utils'

export const ATTRIBUTE_ICONS: Record<FirewallConditionAttribute, LucideIcon> = {
  ip: Fingerprint,
  host: Server,
  path: Route,
  method: Send,
  protocol: Network,
  headers: Tags,
  query: SearchCode,
  queryKeys: KeyRound,
  accept: Check,
  acceptLanguage: Languages,
  cookie: Cookie,
  country: Globe2,
  continent: Globe,
  city: Building2,
  state: MapPin,
  postalCode: Mailbox,
  latitude: LocateFixed,
  longitude: Compass,
  timeZone: Clock,
  weatherCode: Cloud,
  isp: Wifi,
  autonomousSystemNumber: Hash,
  autonomousSystemOrganization: Building,
  connectionType: Cable,
  connectionUsageType: Activity,
  connectionOrganization: Building,
  os: Monitor,
  browser: AppWindow,
  userAgent: UserRound,
  sessionAge: Timer,
  mfaAge: ShieldCheck,
}

interface ConditionAttributeSelectProps {
  value: FirewallConditionAttribute
  onValueChange: (value: FirewallConditionAttribute) => void
  resourceType: FirewallResourceType
  disabled?: boolean
  premiumGeoEnabled: boolean
  triggerClassName?: string
}

export function ConditionAttributeSelect({
  value,
  onValueChange,
  resourceType,
  disabled = false,
  premiumGeoEnabled,
  triggerClassName,
}: ConditionAttributeSelectProps) {
  const t = useT()
  const [open, setOpen] = useState(false)
  const { rootRef, portalContainer, modal, handleOpenChange } =
    useModalAwarePopover()

  const selectedLabel =
    FIREWALL_CONDITION_ATTRIBUTES.find((attr) => attr.value === value)?.label ??
    value
  const SelectedIcon = ATTRIBUTE_ICONS[value] ?? Route
  const groups = FIREWALL_CONDITION_ATTRIBUTE_GROUPS.map((group) => ({
    ...group,
    attributes: group.attributes.filter((attr) =>
      isAttributeAvailable(attr.value, resourceType),
    ),
  })).filter((group) => group.attributes.length > 0)

  return (
    <div ref={rootRef} className="contents">
      <Popover
        open={open}
        modal={modal}
        onOpenChange={(nextOpen) => {
          handleOpenChange(nextOpen)
          setOpen(nextOpen)
        }}
      >
        <PopoverTrigger asChild>
          <Button
            type="button"
            variant="outline"
            role="combobox"
            aria-expanded={open}
            disabled={disabled}
            className={cn(
              'h-9 min-w-0 flex-1 justify-between gap-2 text-[13px] font-normal',
              triggerClassName,
            )}
          >
            <span className="flex min-w-0 items-center gap-2 truncate">
              <SelectedIcon className="h-3.5 w-3.5 shrink-0 text-muted-foreground" />
              <span className="truncate">{t(selectedLabel)}</span>
            </span>
            <ChevronDown className="h-4 w-4 shrink-0 opacity-50" />
          </Button>
        </PopoverTrigger>
        <PopoverContent
          container={portalContainer}
          className="max-h-[min(320px,var(--radix-popover-content-available-height))] w-[var(--radix-popover-trigger-width)] overflow-hidden p-0"
          align="start"
          onWheelCapture={(event) => {
            event.stopPropagation()
          }}
          onCloseAutoFocus={(event) => {
            if (portalContainer) event.preventDefault()
          }}
        >
          <Command className="overflow-hidden">
            <CommandInput
              placeholder={t('Search types...')}
              className="h-9 text-[13px]"
              onKeyDown={(event) => {
                if (
                  event.key === 'ArrowDown' ||
                  event.key === 'ArrowUp' ||
                  event.key === 'Home' ||
                  event.key === 'End' ||
                  event.key === 'Enter' ||
                  event.key === 'Escape'
                ) {
                  return
                }
                event.stopPropagation()
              }}
            />
            <CommandList className="min-h-[180px] max-h-[240px] overflow-y-auto overscroll-contain">
              <CommandEmpty className="py-4 text-center text-[13px] text-muted-foreground">
                {t('No types found')}
              </CommandEmpty>
              {groups.map((group) => (
                <CommandGroup key={group.label} heading={t(group.label)}>
                  {group.attributes.map((attr) => {
                    const ItemIcon = ATTRIBUTE_ICONS[attr.value] ?? Route
                    const premiumLocked =
                      isPremiumAttribute(attr.value) && !premiumGeoEnabled
                    const label = t(attr.label)
                    const groupLabel = t(group.label)

                    return (
                      <CommandItem
                        key={attr.value}
                        value={`${attr.value} ${label} ${groupLabel}`}
                        disabled={premiumLocked}
                        className="text-[13px]"
                        onSelect={() => {
                          onValueChange(attr.value)
                          setOpen(false)
                        }}
                      >
                        <span className="flex min-w-0 items-center gap-2">
                          <ItemIcon className="h-3.5 w-3.5 shrink-0 text-muted-foreground" />
                          <span className="truncate">{label}</span>
                          {isPremiumAttribute(attr.value) ? (
                            <span className="rounded bg-muted px-1.5 py-0.5 text-[10px] font-medium uppercase tracking-wide text-muted-foreground">
                              {premiumLocked
                                ? t('Premium Geo DB required')
                                : t('Premium')}
                            </span>
                          ) : null}
                        </span>
                      </CommandItem>
                    )
                  })}
                </CommandGroup>
              ))}
            </CommandList>
          </Command>
        </PopoverContent>
      </Popover>
    </div>
  )
}
import { useMemo, useState } from 'react'
import { useParams } from '@tanstack/react-router'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { NumberInput } from '@/components/ui/number-input'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { SearchableSelect } from '@/components/global/shared/SearchableSelect'
import { Plus, Trash2, Route } from 'lucide-react'
import {
  FIREWALL_HTTP_METHODS,
  createEmptyConditionDraft,
  defaultOperatorForAttribute,
  getOperatorsForAttribute,
  isDynamicKeyAttribute,
  isNoValueOperator,
  isOperatorAllowedForAttribute,
  isAttributeAvailable,
  isSecondsAttribute,
  isTextMatchOperator,
  type FirewallConditionAttribute,
  type FirewallConditionDraft,
  type FirewallConditionOperator,
  type FirewallResourceType,
} from '@/lib/firewall/conditions'
import {
  FIREWALL_CREATABLE_ACTIONS,
  getFirewallActionDotClass,
  getFirewallActionLabel,
  type FirewallCreatableAction,
} from '@/lib/firewall/actions'
import {
  useContinents,
  useCountries,
  useProjectAddons,
} from '@/lib/react-query/hooks'
import {
  ADDON_KEY_PREMIUM_GEO_DB,
  findActiveOrPendingAddon,
} from '@/lib/billing/addons'
import { useConsoleProfile } from '@/hooks/use-console-profile'
import { cn } from '@/lib/utils'
import { useT } from '@/lib/i18n/translate'
import {
  createTimeUnitPair,
  fromSeconds,
  toSeconds,
  type TimeUnit,
} from '@/lib/utils/time-unit-converter'
import type { ReactNode } from 'react'
import {
  ATTRIBUTE_ICONS,
  ConditionAttributeSelect,
} from './ConditionAttributeSelect'

/** Examples only. Never use bare `/` - it looks like a real value when the field is empty. */
const PATH_PLACEHOLDERS: Record<FirewallResourceType, string> = {
  api: 'e.g. /v1/account',
  functions: 'e.g. /api',
  sites: 'e.g. /about',
}

/**
 * Example value hints for attributes rendered by the generic text input (the
 * `default` case below). Attributes with a dedicated input branch set their own
 * placeholder; anything absent here falls back to a plain "Value".
 */
const ATTRIBUTE_VALUE_PLACEHOLDERS: Partial<
  Record<FirewallConditionAttribute, string>
> = {
  protocol: 'e.g. https',
  queryKeys: 'e.g. redirect',
  accept: 'e.g. application/json',
  acceptLanguage: 'e.g. en-US',
  cookie: 'e.g. a_session_console',
  postalCode: 'e.g. 94107',
  latitude: 'e.g. 37.7749',
  longitude: 'e.g. -122.4194',
  timeZone: 'e.g. America/Los_Angeles',
  weatherCode: 'e.g. USCA0746',
  isp: 'e.g. Comcast Cable',
  autonomousSystemNumber: 'e.g. 15169',
  autonomousSystemOrganization: 'e.g. Google LLC',
  connectionType: 'e.g. Cellular',
  connectionUsageType: 'e.g. residential',
  connectionOrganization: 'e.g. Google LLC',
}

interface ConditionsBuilderProps {
  conditions: FirewallConditionDraft[]
  onChange: (
    next:
      | FirewallConditionDraft[]
      | ((prev: FirewallConditionDraft[]) => FirewallConditionDraft[]),
  ) => void
  disabled?: boolean
  resourceType?: FirewallResourceType
  /** When set, renders the Vercel-style Then action row. */
  action?: FirewallCreatableAction
  onActionChange?: (action: FirewallCreatableAction) => void
  /** When true, shows the Then action but does not allow changing it. */
  actionReadOnly?: boolean
  /** Extra fields under the Then action (rate limit / redirect). */
  actionExtras?: ReactNode
  className?: string
}

function RailLabel({ children }: { children: ReactNode }) {
  return (
    <span className="relative z-10 bg-card px-1.5 text-[13px] font-semibold leading-none text-foreground">
      {children}
    </span>
  )
}

const DURATION_UNITS: TimeUnit[] = ['seconds', 'minutes', 'hours', 'days']

const DURATION_UNIT_LABELS: Record<string, string> = {
  seconds: 'Seconds',
  minutes: 'Minutes',
  hours: 'Hours',
  days: 'Days',
}

/** Prefilled when switching to session / MFA age: shows as 5 minutes. */
const DEFAULT_DURATION_SECONDS = '300'

/**
 * Duration input for session / MFA age. The draft value stays in seconds; the
 * unit starts at the one with the smallest whole value (300 → 5 minutes).
 */
function ConditionDurationInput({
  value,
  disabled,
  onChange,
}: {
  value: string
  disabled?: boolean
  onChange: (value: string) => void
}) {
  const t = useT()
  const seconds = Number(value) || 0
  const [unit, setUnit] = useState<TimeUnit>(
    () => createTimeUnitPair(seconds, { units: DURATION_UNITS }).unit,
  )
  // Six decimals keep one-second resolution in every unit (a day's error
  // stays under 0.05s), so the shown value always maps back to the stored one.
  const amount = Number(fromSeconds(seconds, unit).toFixed(6))

  return (
    <div className="flex w-full gap-2">
      <NumberInput
        value={amount}
        min={0}
        disabled={disabled}
        className="h-9 min-w-0 flex-1 font-mono text-[13px] tabular-nums"
        onValueChange={(next) =>
          onChange(String(Math.round(toSeconds(next, unit))))
        }
      />
      <Select
        value={unit}
        disabled={disabled}
        onValueChange={(next) => setUnit(next as TimeUnit)}
      >
        <SelectTrigger className="h-9 w-[9.5rem] shrink-0 text-[13px]">
          <SelectValue />
        </SelectTrigger>
        <SelectContent>
          {DURATION_UNITS.map((option) => (
            <SelectItem key={option} value={option}>
              {t(DURATION_UNIT_LABELS[option])}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
    </div>
  )
}

/**
 * Key input for headers / query conditions. The API prefix (`headers.` /
 * `query.`) is added automatically on submit.
 */
function ConditionKeyInput({
  attribute,
  value,
  disabled,
  onChange,
}: {
  attribute: 'headers' | 'query'
  value: string
  disabled?: boolean
  onChange: (value: string) => void
}) {
  const t = useT()
  return (
    <Input
      value={value}
      disabled={disabled}
      placeholder={
        attribute === 'headers'
          ? t('Key, e.g. x-custom-header')
          : t('Key, e.g. token')
      }
      className="h-9 w-full font-mono text-[13px]"
      onChange={(e) => onChange(e.target.value)}
    />
  )
}

function ConditionValueInput({
  attribute,
  operator,
  value,
  disabled,
  pathPlaceholder,
  onChange,
}: {
  attribute: FirewallConditionAttribute
  operator: FirewallConditionOperator
  value: string
  disabled?: boolean
  pathPlaceholder: string
  onChange: (value: string) => void
}) {
  const t = useT()
  const { data: countriesData, isLoading: countriesLoading } = useCountries()
  const { data: continentsData } = useContinents()

  const countryItems = useMemo(
    () =>
      (countriesData?.countries ?? []).map((country) => {
        const code = country.code.toUpperCase()
        return {
          value: code,
          label: country.name,
          description: code,
          inlineDescription: true,
          searchText: `${country.name} ${code} ${country.code}`,
        }
      }),
    [countriesData?.countries],
  )

  switch (attribute) {
    case 'method':
      return (
        <Select
          value={value || undefined}
          disabled={disabled}
          onValueChange={onChange}
        >
          <SelectTrigger className="h-9 w-full">
            <SelectValue placeholder={t('Select method')} />
          </SelectTrigger>
          <SelectContent>
            {FIREWALL_HTTP_METHODS.map((method) => (
              <SelectItem key={method} value={method}>
                {method}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      )

    case 'country':
      // Text-match operators need a free-text value; a country picker can only
      // express an exact code, matching usage where country is a string column.
      if (isTextMatchOperator(operator)) {
        return (
          <Input
            value={value}
            disabled={disabled}
            placeholder={t('e.g. US')}
            className="h-9 w-full font-mono text-[13px]"
            onChange={(e) => onChange(e.target.value)}
          />
        )
      }
      return (
        <SearchableSelect
          value={value.toUpperCase()}
          onValueChange={onChange}
          items={countryItems}
          placeholder={t('Select a country')}
          searchPlaceholder={t('Search countries...')}
          emptyMessage={t('No country found.')}
          disabled={disabled}
          isFetching={countriesLoading}
          triggerClassName="h-9 w-full"
        />
      )

    case 'continent':
      // Text-match operators need a free-text value, same as country.
      if (isTextMatchOperator(operator)) {
        return (
          <Input
            value={value}
            disabled={disabled}
            placeholder={t('e.g. EU')}
            className="h-9 w-full font-mono text-[13px]"
            onChange={(e) => onChange(e.target.value)}
          />
        )
      }
      return (
        <Select
          value={value || undefined}
          disabled={disabled}
          onValueChange={onChange}
        >
          <SelectTrigger className="h-9 w-full">
            <SelectValue placeholder={t('Select a continent')} />
          </SelectTrigger>
          <SelectContent>
            {(continentsData?.continents ?? []).map((continent) => (
              <SelectItem
                key={continent.code}
                value={continent.code.toUpperCase()}
              >
                {continent.name}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      )

    case 'path':
      return (
        <Input
          value={value}
          disabled={disabled}
          placeholder={pathPlaceholder}
          className="h-9 w-full font-mono text-[13px]"
          onChange={(e) => onChange(e.target.value)}
        />
      )

    case 'ip':
      // CIDR blocks only match on equal / not equal server-side.
      return (
        <Input
          value={value}
          disabled={disabled}
